    "desc item Heavy sand": "Neredeyse siyah ve elde, kumun hakkı olmayacak kadar ağır — bir demircinin mıknatıs taşı içinden geçip tüylenmiş çıkıyor. Düzlükler yılda iki kez bir damarına kadar aşınıyor ve deniz onu geri koyuyor. Kimse satmıyor, çünkü kimse ona ulaşamıyor.",
