    "noise Adventurer's guild 28": "...ciddiyim, öyle bir büyü hiç görmedim...",
    "noise Adventurer's guild 29": "...gölgeler canlıymış gibiydi...",
    "noise Adventurer's guild 30": "...aslında, onu ben görmedim ama...",
    "noise Adventurer's guild 31": "...takım arkadaşım gölgelerin duvardan koptuğuna yemin ediyor...",
    "noise Adventurer's guild 32": "...sonra bir kazık şeklini aldılar...",
    "noise Adventurer's guild 33": "...tek bir hamle ve kat boss'u yok oldu...",
    "noise Adventurer's guild 34": "Tamam, şimdi, bir kobold düşün...",
    "noise Adventurer's guild 35": "Tamam, şimdi de üç kobold düşün. Bir trençkotun içinde...",
    "noise Adventurer's guild 36": "Klasik, değil mi?",
    "noise Adventurer's guild 37": "Şimdi bir trençkotun içinde, kobold taklidi yapan üç şişko sıçan düşün",
