    "noise Adventurer's guild 39": "Üst üste dizilmiş, tek bir büyük trençkot giymiş...",
    "noise Adventurer's guild 40": "Hayır, ciddiyim!",
    "noise Adventurer's guild 41": "Yemin ederim, kuzenimin abisinin köpeğinin kuaförünün halasının kocası bunu kendi gözleriyle gördü!",
    "noise Adventurer's guild 42": "...ama en çılgın kısmını biliyor musun?",
    "noise Adventurer's guild 43": "Yemin ederim ikisinin kedi kuyruğu vardı...",
    "noise Adventurer's guild 44": "Sarhoş değildim, kedi kuyrukları ve kedi kulakları vardı...",
    "noise Adventurer's guild 45": "...gerçi diğer ikisi insan gibiydi",
    "noise Adventurer's guild 46": "İki nekomimi vardı, bir oğlan bir kız...",
    "noise Adventurer's guild 47": "...ve yanlarında iki insan daha vardı...",
    "noise Adventurer's guild 48": "...nasıl hâlâ ünlü olmadıklarını gerçekten anlamıyorum, ama...",
    "noise Adventurer's guild 49": "...bence ONUNLA bile dövüşebilirlerdi...",
    "noise Adventurer's guild 50": "...evet, tabii takım olarak, tek başına değil...",
    "noise Adventurer's guild 51": "...ne yazık ki kim bilir nereye çekilip emekli oldu.",
