    "action hike down river starting": "Nehir kıyısı boyunca vahşi doğada yürümeyi dene",
    "action hike down river desc": "Gerçekten çok uzun sürebilir, ama o kocaman yengeçlerin yuvasını bulmanın tek yolu bu. Yoksa kocaman yengecin yuvası mıydı?",
