    "action hike down river success": "Bir günden fazla yürüdükten sonra, sonunda nehrin tanınabilir işaretleri ve yengeç izleri olan, oldukça açık bir noktasına varıyorsun. Köyden çok uzak geliyor, ama buraya yine gelebileceğinden, hem de daha hızlı geleceğinden eminsin",
