    "action bridge mat delivery starting": "Malzemeleri inşaat alanına götür",
    "action bridge mat delivery desc": "100 odun kütüğünü ve 500 taş tuğlayı inşaat alanına götür",
    "action bridge mat delivery during": "Teslim ediliyor",
    "action bridge mat delivery success": "Malzemeleri köprünün kurulacağı yerin yakınına bırakıyorsun",
    "action bridge construction starting": "Köprüyü inşa et",
    "action bridge construction desc": "Köprüyü inşa eden işçilere katıl",
    "action bridge construction during": "İnşa ediliyor",
    "action bridge construction success": "Zanaatkâra son tahtayı yerleştirmesinde yardım ederken, ikiniz de diğer işçilerle birlikte birkaç adım geri çekilip bitmiş köprüye uzun uzun, sessizce bakıyorsunuz. Sonra ilk kişi sonunda tezahürat etmeye başlıyor ve neredeyse anında herkes ona katılıyor. Bu boyuttaki bir yerleşim için basit ama muhteşem bir köprü. Köprünün tabanı sağlam, kalın ahşap tahtalardan yapılmış; üzerinden taşınan her yükü kaldırabilecek ek bir kiriş çatkısıyla desteklenmiş, ayrıca gerektiğinde değiştirmesi de kolay. Yapının tamamı, sudan gururla yükselen iki sağlam taş ayakla taşınıyor; kalın ve nehir ne kadar kabarırsa kabarsın her akıntıya dayanacak biçimde şekillendirilmiş. Bu yapı, titiz bir planlamanın ve azmin anıtı olarak duruyor ve gelecek kuşaklara bir armağan olacak.",
    "action open the gate starting": "Esrarengiz kapıyı açmak için itmeyi dene",
    "action open the gate desc": "Kadim ve kocaman bir kapı, ama belki yeterli güçle ve idmanla en azından bir parmak açıp geçecek kadar boşluk yaratmayı başarabilirsin.",
    "action open the gate during": "Ha babam itiliyor",
    "action open the gate success": "Neredeyse vazgeçmeye hazırken kadim menteşelerin gıcırdadığını duyuyorsun; kapı ağır ağır kımıldıyor. Sonunda daha derine devam edebilirsin!",
    "action climb the mountain starting": "Dağa tırmanmayı dene",
    "action climb the mountain desc": "İyi ve uzun bir halat, gerçek bir tırmanma becerisi ve iyi bir fizik gerektiren çetin bir iş. Biraz zaman alacak, o yüzden yolun yarısında enerjinin tükenmeyeceğinden emin olmalısın.",
    "action climb the mountain during": "Yukarı tırmanılıyor",
    "action climb the mountain success": "Bir şekilde başardın, ta yukarıya kadar tırmandın! Yol boyunca bağladığın halat sayesinde, bundan sonraki inip çıkmalar çok daha kolay olacak.",
    "action climb the mountain fail random_loss 1": "Neredeyse başarıyordun, ama bir noktada oynak çıkan bir kayaya tutundun. Bir dahakine daha dikkatli ol!",
