    "action create lake camp starting": "Dev yengecin yuvasının üstüne bir kamp kur",
    "action create lake camp desc": "Yeni bir kamp yeri kurmak için buraya bir karyola, ateş çukuru ve depo sandığı yerleştir. Hem bu bölgede dinlenmek hem de daha ileri keşifler için gerekli olacak",
