    "action rappel waterfall starting": "Şelalenin yanındaki kaya duvarından halatla inmeyi dene",
    "action rappel waterfall desc": "O kadar zor görünmüyor, ama yine de iyi ve uzun bir halat, tırmanmada ustalık ve formda bir beden gerektiren yorucu bir iş. Bayağı zaman alacak, o yüzden seni bekleyen iş için hazırlıklı ol",
    "action rappel waterfall during": "Yardan halatla iniliyor",
    "action rappel waterfall success": "Yavaş ve titiz bir işti, ama kaya duvarı boyunca güvenli ve sağlam bir geçit sabitlemeyi başardın. Bu, bundan sonraki inip çıkmaları belirgin biçimde hızlandıracak",
    "action create lake climbing starting": "Halatla iniş çalışma noktası hazırla",
    "action create lake climbing desc": "Buradaki kaya duvarı, halatla iniş gibi ileri tırmanma tekniklerini çalışmak için iyi bir yer olur",
    "action create lake climbing during": "Güvenli bir iniş noktası aranıyor",
    "action create lake climbing success": "Bir saat sonra, uçurumun kenarına yakın sığ bir çıkıntının üstüne biraz halatı güvenle sabitlemeyi başarıyorsun. Kaya duvarının tamamından inmeyi denemeden önce burada çalışabilirsin",
    "action create lake weightlifting starting": "Kızak çekme idmanı için bir kayayı sar",
    "action create lake weightlifting desc": "Yakındaki büyük kayalara bakınca, birini halatla kumsalda sürüklemenin ya da çekmenin iyi bir kuvvet idmanı olabileceğini düşünüyorsun",
    "action create lake weightlifting during": "Kaya sarılıyor",
    "action create lake weightlifting success": "Yaklaşık bir saat sonra, bir kayayı halatla güvenle sarmayı başarıyorsun. Ucundan kavrayıp tüm gücünle çekince kaya seninle birlikte santim santim ilerliyor",
