    "action learn forage starting": "İzciye buranın otları ve sebzeleri hakkında sana öğretmesini söyle",
    "action learn forage desc": "İzci ilginç yerel bitkilerden söz etmişti, belki onları sana öğretebilir",
    "action learn forage during": "İzciden toplayıcılık öğreniliyor",
    "action learn forage success": "İzci, dış bataklıklarda yetişen otları, kök sebzelerini ve yumruları anlatıyor. Bu noktada onları kendin de bulabileceğinden eminsin",
    "action learn forage fail random_loss 1": "İzci buranın bitkilerinin görünüşünü ve kullanımını anlatmaya çalışıyor, ama sana söylediklerini bir türlü içine sindiremiyorsun",
    "action learn forage fail random_loss 2": "İzci buranın bitkilerinin görünüşünü ve kullanımını anlatmaya çalışıyor, ama bir saat boyunca aklın onun son zamanlarda sana anlattığı her şeye gidiyor ve öğretmeye çalıştığına odaklanmakta zorlanıyorsun",
    "action learn forage fail random_loss 3": "İzci buranın bitkilerinin görünüşünü ve kullanımını anlatmaya çalışıyor, ama acısı şu an sana düzgünce bir şey öğretmesine engel oluyor",
    "action learn forage fail random_loss 4": "İzci buranın bitkilerinin görünüşünü ve kullanımını anlatmaya çalışıyor, ama sana söylediği hiçbir şey pek işe yaramıyor",
    "action learn forage fail random_loss 5": "İzci buranın bitkilerinin görünüşünü ve kullanımını anlatmaya çalışıyor, ama sana zaten öğrendiğin şeyleri söylüyor",
    "action learn forage fail random_loss 6": "İzci buranın bitkilerinin görünüşünü ve kullanımını anlatmaya çalışıyor, ama ikinizin de dikkati dağılıyor ve bir saati başka bir şeyden konuşarak geçiriyorsunuz. İyi geldi",
    "action follow the trail unlock": "Dövüşlerinin bir anında, hayvanların çiğnediği bir yol fark ediyorsun. Kurda benzeyen ama çok daha büyük bir sürü ayak izi var...",
    "action What was that noise? unlock": "Yaban domuzlarıyla dövüşürken kuzeyden tuhaf bir ses duydun. Ne olabilir ki?",
    "action carry grain fail unable_to_begin 1": "Biraz deniyorsun, ama bu iş için yeterince formda olmadığını çabucak anlıyorsun.",
    "action pull cart fail unable_to_begin 1": "Deniyorsun, deniyorsun, ama kıpırdamıyor",
    "action convince horse fail conditional_loss 1": "Ne yaparsan yap, at oralı olmuyor. Hayvanlarla gerçek bir tecrüben olsaydı belki...",
    "action carry cart fail conditional_loss 1": "Meğer bunun için fazla zayıfsın; tabii ki öylesin, ne düşünüyordun ki?",
    "action dig canal fail unable_to_begin 1": "Önce bir kürek edinmelisin. Belki birinin yedeği vardır, ya da köy pazarından bir tane alabilirsin?",
    "action bridge mat delivery fail unable_to_begin 1": "Yeterli malzemen yok",
    "action open the gate fail conditional_loss 1": "Elinden geleni yapsan da bunun için fazla zayıf olduğunu hissedebiliyorsun. Önce güçlenmelisin.",
    "action climb the mountain fail conditional_loss 1": "Elinden geleni yapsan da daha fazla idman olmadan bunu başaramayacağını hissedebiliyorsun",
    "action climb the mountain fail unable_to_begin 1": "Hazır göründüğün hâlde önemli bir teçhizatın eksik olduğunu fark ediyorsun: bunun için iyi ve uzun bir halat şart olacak, hele bir noktada geri inmek istiyorsan.",
    "action create camp fail conditional_loss 1": "Kamp malzemen yok!",
    "action follow ant trail fail unable_to_begin 1": "Kürek olmadan bunu yapamazsın!",
    "action create lake camp fail conditional_loss 1": "Kamp malzemesi olmadan kamp kurmak zor olacak!",
    "action rappel waterfall fail conditional_loss 1": "Yardan inmenin kolay olacağını kendine söylemene rağmen, yolun başta beklediğinden çok daha tehlikeli olduğunu fark ediyorsun. Belki daha tecrübeli bir dağcı bu tehlikelerin üstesinden gelebilirdi",
    "action rappel waterfall fail random_loss 1": "Güzergâh yukarıdan daha kolay görünüyordu, ama kaygan kaya duvarı ve kötü basamaklar başladıktan kısa süre sonra seni başarısızlığa sürükledi",
    "action rappel waterfall fail unable_to_begin 1": "Zihnen hazır olsan da önemli bir teçhizatın eksik olduğunu fark ediyorsun -- halat! Bunun için halat bir tür zorunluluk, hele inişten sağ çıkmak istiyorsan!",
    "action create lake climbing fail conditional_loss 1": "Halat olmadan inmek zor olacak!",
    "action create lake weightlifting fail conditional_loss 1": "Bir şey sarmadan önce halata ihtiyacın olacak!",
    "action search1 fail conditional_loss 1": "O kadar derine inmek için suya daha çok alışman ve akciğer kapasiteni artırman gerekiyor",
    "action search2 fail conditional_loss 1": "O kadar derine inmek için suya daha çok alışman ve akciğer kapasiteni artırman gerekiyor",
    "action learn forage fail conditional_loss 1": "İzci buranın bitkilerinin görünüşünü ve kullanımını anlatmaya çalışıyor, ama neden bahsettiğini anlamakta zorlanıyorsun. Belki daha iyi bir otacı olsan daha kolay olurdu",
    "action gaze fail random_loss 1": "Bu ormanın karşına çıkarabileceği her şeyi çoktan göğüsleyebileceğini düşünmüş olabilirsin. Ama önünde uzanan bölüm şimdiye dek gördüğün her şeyden daha heybetli.\n\n\nGölden gelen nehir karanlıkta kayboluyor; ağaç örtüsü o kadar yoğun ki ışığı içeri bırakmıyor. Oradaki ağaçlar daha büyük, daha sık... Daha kadim.\n\n\nUzakta uçan bir kuşa benzeyen şeyin ayrıntılarını seçmeye çalışıyorsun. Dört bacağı var... [devamı gelecek]",

